let workOrderSeq = 0;
export const workOrder = (options: { readonly state: WorkOrder["state"]; readonly created_at?: string; readonly run_unit_id?: ExecutionUnitId; readonly id?: string }): WorkOrder => {
  workOrderSeq += 1;
